def run(records):
    """One item per session: the user's requests, then every tool call the agent made.

    Sessions without tool calls cannot have run anything and are left out."""
    sessions = {}
    for r in records:
        s = sessions.setdefault(
            r["session_id"], {"id": r["session_id"], "lines": [], "record_ids": [], "calls": 0}
        )
        if r["kind"] == "tool_call":
            s["calls"] += 1
            s["lines"].append("tool call: " + r["content"])
        else:
            s["lines"].append("user: " + r["content"])
        s["record_ids"].append(r["id"])
    return [
        {"id": s["id"], "text": "\n".join(s["lines"]), "record_ids": s["record_ids"]}
        for s in sessions.values()
        if s["calls"]
    ]
